insert into public.post_sources (post_id, source_id, sort) values ((select id from public.posts where type = 'article' and slug = 'is-this-noahs-ark-durupinar-evidence'), '16ded1ee-7084-51b9-bbc8-88cd1ca05eb0', 4);
insert into public.posts (type, slug, title, dek, topic_id, author_id, status, featured, reading_minutes, hero, body, footnotes, corrections, claim, dispatch, related_slug) values ('article', '340000-threads-how-connected-is-the-bible', '340,000 threads: how connected is the Bible, really?', 'The Interwoven Word, part one. Where the famous cross-reference numbers come from, what counts as a connection, and what the web of links can and can’t tell us.', (select id from public.topics where slug = 'bible-manuscripts'), (select id from public.authors where slug = 'editor'), 'draft', false, 9, '{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d3/Codex_Sinaiticus.jpg/1920px-Codex_Sinaiticus.jpg","alt":"An open facsimile of Codex Sinaiticus with columns of Greek text","caption":"A facsimile of Codex Sinaiticus, a fourth-century Greek Bible.","credit":"PotatoCow25 / Wikimedia Commons, CC0","credit_url":"https://commons.wikimedia.org/wiki/File:Codex_Sinaiticus.jpg"}'::jsonb, '[{"type":"p","text":"Open almost any study Bible and you will find a narrow column of references running down the middle of the page. Put all of those links together and the numbers get startling. One freely available dataset, compiled mostly from the classic Treasury of Scripture Knowledge, contains about 340,000 cross-references between verses.[^1] A well-known visualization by Chris Harrison and Christoph Römhild drew 63,779 of them as arcs across the 66 books, producing an image that looks like a rainbow woven over the whole Bible.[^2]"},{"type":"p","text":"This series, The Interwoven Word, is about those threads: where they come from, which ones are strongest, and what they suggest about the book that holds them. It starts with a question every careful reader should ask: what exactly is being counted?"},{"type":"h2","text":"Not every thread is the same"},{"type":"p","text":"A cross-reference is an editor’s judgment that two verses belong together. Some links are unmistakable; others are loose. Sorting them into kinds is the first step to weighing them."},{"type":"list","items":["**Quotations.** One writer cites another’s words, often with a formula such as “as it is written.” Matthew 21:5 quotes Zechariah 9:9 almost word for word.","**Allusions.** A writer borrows an image or phrase without naming it. When John the Baptist calls Jesus “the Lamb of God” (John 1:29), he draws on a long line of lambs in Israel’s story.","**Patterns.** Events or figures prefigure later ones. Isaac carries the wood up the mountain (Genesis 22:6); John notes that Jesus went out “carrying his own cross” (John 19:17).","**Shared themes and words.** Two passages speak of the same subject, such as covenant, exile or the shepherd. These are the weakest links and the most numerous."]},{"type":"p","text":"Big totals like 340,000 include all four kinds. That does not make the number meaningless, but it does mean the strength of the case lies less in the total than in the quality of particular threads."},{"type":"h2","text":"Why the strong threads are remarkable"},{"type":"p","text":"The Bible was written over roughly 1,500 years, by dozens of authors, in three languages, on three continents. Many of its writers could not have known how later books would use their words. Yet the major threads run in one direction with surprising consistency: promise to fulfillment, shadow to substance, from the seed promised in Genesis 3:15 to the Lamb on the throne in Revelation 5:6."},{"type":"p","text":"A skeptic can answer that later writers deliberately wove their work into earlier texts, and sometimes they did; the New Testament writers say so openly. The interesting cases are the ones no later writer could have arranged: patterns built into the Old Testament itself, centuries before anyone claimed them, and small details across separate accounts that fit together without any sign of design. Those are the threads this series will follow."},{"type":"h2","text":"What the series will cover"},{"type":"list","items":["Undesigned coincidences: when the Gospels explain each other by accident.","The lamb from Genesis to Revelation, traced book by book.","Psalm 22 and the crucifixion, including the Dead Sea Scrolls evidence.","“The Bereans test”: one New Testament quotation of the Old Testament at a time, checked in context."]},{"type":"callout","title":"Coming to the site","text":"We are building a cross-reference explorer from the open dataset, so that beside any verse you read on Sifted Truth you will be able to see how many others connect to it and follow the threads yourself."}]'::jsonb, '[{"n":1,"text":"OpenBible.info, Bible Cross References, derived mainly from the Treasury of Scripture Knowledge.","source_id":"801bdc8d-f33e-c87b-d2ee-ad2f0416dc71"},{"n":2,"text":"Harrison and Römhild, Bible cross-references visualization (2007).","source_id":"b7b9f43c-f2d4-a2dd-bccf-c98163df3a6d"}]'::jsonb, '[]'::jsonb, null, null, null)
