insert into public.post_sources (post_id, source_id, sort) values ((select id from public.posts where type = 'article' and slug = '340000-threads-how-connected-is-the-bible'), '1dba4b65-2d4d-8eff-5bb2-ae5b0b28403c', 2);
insert into public.posts (type, slug, title, dek, topic_id, author_id, status, featured, reading_minutes, hero, body, footnotes, corrections, claim, dispatch, related_slug) values ('article', 'undesigned-coincidences-gospels-explain-each-other', 'Undesigned coincidences: when the Gospels explain each other by accident', 'The Interwoven Word, part two. Small details in one Gospel answer questions raised by another, in ways no author seems to have planned. Why that matters for reliability.', (select id from public.topics where slug = 'apologetics'), (select id from public.authors where slug = 'editor'), 'draft', false, 10, '{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3e/Northern_views._Ain_Tabgha._Mosaic_floor._Loaves_and_fishes_LOC_matpc.02800.jpg/1920px-Northern_views._Ain_Tabgha._Mosaic_floor._Loaves_and_fishes_LOC_matpc.02800.jpg","alt":"An ancient floor mosaic of a basket of loaves between two fish","caption":"The loaves-and-fishes mosaic at Tabgha on the Sea of Galilee.","credit":"Matson Photo Service (Library of Congress) / Wikimedia Commons, public domain","credit_url":"https://commons.wikimedia.org/wiki/File:Northern_views._Ain_Tabgha._Mosaic_floor._Loaves_and_fishes_LOC_matpc.02800.jpg"}'::jsonb, '[{"type":"p","text":"Detectives and lawyers know the pattern. Two witnesses tell the same story in their own words. One mentions a detail that seems odd. The other, telling a different part of the story, mentions something that explains it, without seeming to notice. Neither account was written to fit the other, yet they fit. That kind of unplanned agreement is hard to fake."},{"type":"p","text":"Christian writers have used this argument since William Paley applied it to Paul’s letters and Acts in 1790. J. J. Blunt extended it across the whole Bible in 1847, and philosopher Lydia McGrew revived and refined it in 2017.[^1] They call these links undesigned coincidences."},{"type":"h2","text":"Why did Jesus ask Philip?"},{"type":"p","text":"Before feeding the five thousand, Jesus turns to one disciple and asks, “Where can we buy bread for these people to eat?” (John 6:5). Why Philip, of all the twelve? John never says."},{"type":"p","text":"Luke supplies the answer without meaning to. He places the feeding near a town called Bethsaida (Luke 9:10). John, in a different chapter, mentions in passing that Philip was from Bethsaida (John 1:44; John 12:21). Jesus asked the local man where to buy bread. Neither writer connects the dots; the dots connect themselves.[^2]"},{"type":"h2","text":"Why so many people, and why green grass?"},{"type":"p","text":"Mark says that before the same miracle, so many people were “coming and going” that the disciples had no time even to eat (Mark 6:31). He also notices that the crowd sat down on “the green grass” (Mark 6:39), a small detail in a dry land."},{"type":"p","text":"John explains both without referring to either. He notes that “the Jewish Feast of the Passover was near” (John 6:4). Passover falls in spring, when the hillsides by the Sea of Galilee are green, and when crowds of pilgrims would be on the roads heading toward Jerusalem."},{"type":"h2","text":"Why did they wait until evening?"},{"type":"p","text":"Matthew says that “when evening came,” people brought many sick to Jesus to be healed (Matthew 8:16). Why wait all day? Mark’s account of the same day reveals that it was the Sabbath (Mark 1:21). The Sabbath ended at sundown, and only then could people carry the sick through the streets (Mark 1:32)."},{"type":"h2","text":"What the argument shows, and what it doesn’t"},{"type":"p","text":"One coincidence can be luck. The argument draws its strength from the number of them. Dozens of small, unforced fits across independent accounts are what we expect when writers are describing real events they knew well, and not what we expect from legend or from authors copying and embellishing each other."},{"type":"p","text":"Critics respond that some coincidences can be explained by later editing, or that the authors drew on shared traditions rather than eyewitness memory. Some proposed examples are stronger than others, and the best defenders of the argument say so themselves. The argument does not prove every detail of the Gospels. It does give a concrete, checkable reason to treat them as testimony rather than myth."},{"type":"callout","title":"Check it yourself","text":"Hover over each reference above to read it, then read the surrounding chapters. The point of an undesigned coincidence is that you don’t have to take anyone’s word for it."}]'::jsonb, '[{"n":1,"text":"Paley, Horae Paulinae (1790); Blunt, Undesigned Coincidences (1847); McGrew, Hidden in Plain View (2017).","source_id":"8abe283e-7832-66f5-1264-4b3673016123"},{"n":2,"text":"This example is discussed by both Blunt and McGrew.","source_id":"c173db95-00db-4ae2-c79c-e602461eda53"}]'::jsonb, '[]'::jsonb, null, null, null)
