insert into public.post_sources (post_id, source_id, sort) values ((select id from public.posts where type = 'article' and slug = 'undesigned-coincidences-gospels-explain-each-other'), 'c173db95-00db-4ae2-c79c-e602461eda53', 1);
insert into public.post_sources (post_id, source_id, sort) values ((select id from public.posts where type = 'article' and slug = 'undesigned-coincidences-gospels-explain-each-other'), 'fc7d6384-b0c9-fb23-8dfc-41b89915ba16', 2);
insert into public.posts (type, slug, title, dek, topic_id, author_id, status, featured, reading_minutes, hero, body, footnotes, corrections, claim, dispatch, related_slug) values ('article', 'oldest-bible-verse-ketef-hinnom', 'The oldest Bible verse ever found', 'Two tiny silver scrolls from a Jerusalem tomb carry the priestly blessing of Numbers 6, centuries older than the Dead Sea Scrolls.', (select id from public.topics where slug = 'bible-manuscripts'), (select id from public.authors where slug = 'editor'), 'draft', false, 7, '{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/Ketef_hinom_scrolls.JPG/1920px-Ketef_hinom_scrolls.JPG","alt":"Two small silver scrolls displayed in a museum case","caption":"The Ketef Hinnom silver amulets, Israel Museum, Jerusalem.","credit":"Bachrach44 / Wikimedia Commons, CC BY-SA 3.0","credit_url":"https://commons.wikimedia.org/wiki/File:Ketef_hinom_scrolls.JPG"}'::jsonb, '[{"type":"p","text":"In 1979, a team led by archaeologist Gabriel Barkay was excavating burial caves at Ketef Hinnom, on a ridge just southwest of Jerusalem’s Old City. In a repository beneath one tomb, a young volunteer found two tiny rolled-up silver sheets. They were so fragile that unrolling them took years."},{"type":"h2","text":"What the scrolls say"},{"type":"p","text":"When the silver was finally opened, it held faint Hebrew letters. Both amulets contain a version of the priestly blessing from Numbers 6:24–26: “May the LORD bless you and keep you; may the LORD cause His face to shine upon you…” They also contain the divine name, YHWH."},{"type":"p","text":"They are the oldest known artifacts to quote a passage from the Hebrew Bible, older than the earliest Dead Sea Scrolls by three to four centuries."},{"type":"h2","text":"How old are they?"},{"type":"p","text":"The tomb’s pottery and the style of the letters point to the late seventh or early sixth century BC, the last decades of the kingdom of Judah, just before the Babylonian destruction of Jerusalem. Some scholars proposed a later date. In 2004, a team using new imaging techniques published a fresh edition and concluded that the script fits the late First Temple period.[^1]"},{"type":"h2","text":"Why it matters"},{"type":"p","text":"Some critical theories once held that much of the Pentateuch, including the priestly material in Numbers, was composed after the exile. The amulets don’t settle when Numbers was written as a whole. They do show that this blessing, in wording close to our Bibles, was known and treasured in Jerusalem before the exile, and that ordinary families carried it with them, even into the grave."},{"type":"callout","title":"A blessing that lasted","text":"Families in Judah wore these words for protection while the Babylonian army approached. The same blessing is still spoken over congregations today."}]'::jsonb, '[{"n":1,"text":"Barkay, Lundberg, Vaughn and Zuckerman, BASOR 334 (2004).","source_id":"941f391c-3c9d-d6d8-5661-488545326ffb"}]'::jsonb, '[]'::jsonb, null, null, null)
insert into public.post_sources (post_id, source_id, sort) values ((select id from public.posts where type = 'article' and slug = 'oldest-bible-verse-ketef-hinnom'), '941f391c-3c9d-d6d8-5661-488545326ffb', 0);
insert into public.posts (type, slug, title, dek, topic_id, author_id, status, featured, reading_minutes, hero, body, footnotes, corrections, claim, dispatch, related_slug) values ('dispatch', 'shiloh-2026-season-monumental-building', 'Shiloh dig uncovers more of a tabernacle-sized building and jars of burned grain', 'The 2026 season at the site where Joshua set up the tabernacle adds a wall, gate defenses and a destruction layer to date.', (select id from public.topics where slug = 'archaeology'), (select id from public.authors where slug = 'editor'), 'draft', false, null, '{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/46/Tel_Shiloh_%28biblical_site%29_2017.jpg/1920px-Tel_Shiloh_%28biblical_site%29_2017.jpg","alt":"The hillside site of ancient Shiloh with excavated areas","caption":"Tel Shiloh, where the tabernacle stood according to Joshua 18:1.","credit":"Deg777 / Wikimedia Commons, CC BY-SA 4.0","credit_url":"https://commons.wikimedia.org/wiki/File:Tel_Shiloh_(biblical_site)_2017.jpg"}'::jsonb, '[{"type":"p","text":"Excavators at Shiloh announced three finds from their 2026 season in June. Shiloh is where, according to Joshua 18:1, Israel set up the tabernacle, and where it stood through the days of Eli and young Samuel (1 Samuel 1:3)."},{"type":"p","text":"The team, led by Dr. Scott Stripling of the Associates for Biblical Research, uncovered the southern wall of a monumental building. Its dimensions resemble those of the tabernacle, and finds associated with it include altar horns, ceramic pomegranates and murex shells, used to make purple dye. They also exposed more of the city’s northern gate complex and found three storage jars holding charred olives and wheat in a destruction layer. Radiocarbon tests on that grain should help date the destruction.[^1]"},{"type":"p","text":"Why it matters: a tabernacle-sized building is suggestive, not proof, and the excavators are careful about what they claim. Dated grain from the destruction could test when Shiloh fell, a question tied to Psalm 78:60 and Jeremiah 7:12."}]'::jsonb, '[{"n":1,"text":"Associates for Biblical Research, June 22, 2026.","source_id":"04970937-eb84-e034-af00-f9bdf2e2bb34"}]'::jsonb, '[]'::jsonb, null, '{"label":"Excavation news","original_outlet":"Associates for Biblical Research","original_url":"https://biblearchaeology.org/abr-announces-three-significant-discoveries-at-shiloh-from-2026-season/"}'::jsonb, null)
insert into public.post_sources (post_id, source_id, sort) values ((select id from public.posts where type = 'dispatch' and slug = 'shiloh-2026-season-monumental-building'), '04970937-eb84-e034-af00-f9bdf2e2bb34', 0);
insert into public.posts (type, slug, title, dek, topic_id, author_id, status, featured, reading_minutes, hero, body, footnotes, corrections, claim, dispatch, related_slug) values ('dispatch', 'city-of-david-babylonian-destruction-beams', 'Charred roof beams from Babylon’s burning of Jerusalem found in the City of David', 'Melted plaster sealed the timbers when the roof collapsed in 586 BC. Their tree rings may date the destruction more tightly than ever.', (select id from public.topics where slug = 'archaeology'), (select id from public.authors where slug = 'editor'), 'draft', false, null, '{"src":"https://upload.wikimedia.org/wikipedia/commons/b/ba/Excavation_in_City_of_David_Givaty_parking_lot_Jerusalem_202.jpg","alt":"Excavated stone walls and arches in the Givati Parking Lot dig in Jerusalem","caption":"The Givati Parking Lot excavation in the City of David (file photo).","credit":"Daniel Ventura / Wikimedia Commons, CC BY-SA 4.0","credit_url":"https://commons.wikimedia.org/wiki/File:Excavation_in_City_of_David_Givaty_parking_lot_Jerusalem_202.jpg"}'::jsonb, '[{"type":"p","text":"Excavators from the Israel Antiquities Authority and Tel Aviv University have found burned wooden beams in the Givati Parking Lot dig in the City of David. The beams appear to have roofed an inner courtyard. When the building burned, the roof fell in, and the heat melted the wall plaster, which poured over the charred wood and sealed it under the rubble.[^1]"},{"type":"p","text":"The destruction is linked to the Babylonian conquest of Jerusalem in 586 BC, described in 2 Kings 25:9: Nebuchadnezzar’s commander burned the house of the LORD, the royal palace and every significant building in Jerusalem. The beams have many visible growth rings, which researchers hope could narrow their dating to about a decade. They also plan to identify the tree species."},{"type":"p","text":"Some outlets have described these as beams “from Solomon’s Temple.” The excavators have not said that. The building lies in the City of David, south of the Temple Mount. What the find does offer is a vivid, physical record of the fire the Bible describes."}]'::jsonb, '[{"n":1,"text":"Archaeology Magazine, July 22, 2026.","source_id":"fff648fe-9313-8f27-c049-a90f09d11a91"}]'::jsonb, '[]'::jsonb, null, '{"label":"Excavation news","original_outlet":"Archaeology Magazine","original_url":"https://archaeologymag.com/2026/07/wooden-beams-from-jerusalems-first-temple-destruction/"}'::jsonb, null)
insert into public.post_sources (post_id, source_id, sort) values ((select id from public.posts where type = 'dispatch' and slug = 'city-of-david-babylonian-destruction-beams'), 'fff648fe-9313-8f27-c049-a90f09d11a91', 0);
insert into public.posts (type, slug, title, dek, topic_id, author_id, status, featured, reading_minutes, hero, body, footnotes, corrections, claim, dispatch, related_slug) values ('dispatch', 'tel-eton-standing-stone-hezekiah-reform', 'A standing stone laid on its side may show Hezekiah’s reform reached Judah’s homes', 'At Tel ‘Eton, a 750-kilogram cultic pillar was carefully decommissioned, not smashed, before the Assyrians destroyed the town.', (select id from public.topics where slug = 'archaeology'), (select id from public.authors where slug = 'editor'), 'draft', false, null, '{"src":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4a/Tel-Eton-072.jpg/1920px-Tel-Eton-072.jpg","alt":"Excavated stone foundations at Tel ‘Eton among dry grass","caption":"Excavations at Tel ‘Eton in the Judean Lowlands.","credit":"Bukvoed / Wikimedia Commons, CC BY 4.0","credit_url":"https://commons.wikimedia.org/wiki/File:Tel-Eton-072.jpg"}'::jsonb, '[{"type":"p","text":"A new study by Prof. Avraham Faust of Bar-Ilan University suggests that a standing stone found at Tel ‘Eton, in the Judean lowlands, may be evidence of King Hezekiah’s religious reform.[^1]"},{"type":"p","text":"The stone, about 1.4 meters tall and weighing about 750 kilograms, once stood in the largest room of a large residence known as Building 101. At some point its owners laid it on its side and built a stone platform around it, before the Assyrians destroyed the town at the end of the eighth century BC. 2 Kings 18:4 says Hezekiah “removed the high places, shattered the sacred pillars, and cut down the Asherah poles.”"},{"type":"p","text":"Faust argues the reform may have reached household worship, not only public shrines like those at Arad and Beersheba. The stone was put out of use but treated with respect, not smashed. He does not claim proof, and evidence for Hezekiah’s reform remains debated. The timing, though, fits his reign."}]'::jsonb, '[{"n":1,"text":"Popular Archaeology, June 16, 2026, on Faust’s study in the Jerusalem Journal of Archaeology.","source_id":"00e1ee12-30be-e7f5-2170-c169eaf5a0e4"}]'::jsonb, '[]'::jsonb, null, '{"label":"Scholarship","original_outlet":"Popular Archaeology / Jerusalem Journal of Archaeology","original_url":"https://popular-archaeology.com/article/bar-ilan-university-study-suggests-2700-year-old-standing-stone-massebah-may-provide-fresh-evidence-for-king-hezekiahs-religious-reforms/"}'::jsonb, null)
insert into public.post_sources (post_id, source_id, sort) values ((select id from public.posts where type = 'dispatch' and slug = 'tel-eton-standing-stone-hezekiah-reform'), '00e1ee12-30be-e7f5-2170-c169eaf5a0e4', 0);
